svg.script:
var NS = 'http://www.w3.org/2000/svg', START = -135, SPAN = 270;

function el(tag, attrs, parent, text) {
  var e = document.createElementNS(NS, tag);
  for (var k in attrs) e.setAttribute(k, attrs[k]);
  if (text !== undefined) e.textContent = text;
  if (parent) parent.appendChild(e);
  return e;
}
// point at an angle (0 = straight up, clockwise) and radius from the gauge centre
function pt(deg, r) { var a = deg * Math.PI / 180; return [Math.sin(a) * r, -Math.cos(a) * r]; }
function clamp(v, min, max) { return Math.max(min, Math.min(max, v)); }

function buildGauge(g) {
  var min = +g.dataset.min, max = +g.dataset.max, step = +g.dataset.step, div = +(g.dataset.div || 1);
  function angle(v) { return START + SPAN * (clamp(v, min, max) - min) / (max - min); }

  el('circle', { 'class': 'face', r: 70 }, g);
  if (g.dataset.red) {
    var a = pt(angle(+g.dataset.red), 62), b = pt(START + SPAN, 62);
    el('path', { 'class': 'redline', d: 'M' + a + ' A62 62 0 0 1 ' + b }, g);
  }
  for (var v = min; v <= max; v += step) {
    var p1 = pt(angle(v), 56), p2 = pt(angle(v), 66), p3 = pt(angle(v), 44);
    el('line', { 'class': 'tick', x1: p1[0], y1: p1[1], x2: p2[0], y2: p2[1] }, g);
    el('text', { 'class': 'num', x: p3[0], y: p3[1] + 3 }, g, v / div);
  }
  var needle = el('line', { 'class': 'needle', x1: 0, y1: 0, x2: 0, y2: -48 }, g);
  el('circle', { 'class': 'hub', r: 5 }, g);
  var readout = el('text', { 'class': 'readout', y: 38 }, g);
  el('text', { 'class': 'unit', y: 54 }, g, g.dataset.label);

  g._set = function (value) {
    needle.setAttribute('transform', 'rotate(' + angle(value) + ')');
    readout.textContent = Math.round(value);
  };
  g._set(min);
}

function buildBar(g) {
  var min = +g.dataset.min, max = +g.dataset.max, dec = +(g.dataset.dec || 0);
  var track = g.querySelector('.track'), fill = g.querySelector('.fill'), texts = g.querySelectorAll('text');
  var width = +track.getAttribute('width');
  texts[0].textContent = g.dataset.label;

  g._set = function (value) {
    fill.setAttribute('width', width * (clamp(value, min, max) - min) / (max - min));
    texts[1].textContent = value.toFixed(dec);
    g.classList.toggle('low', g.dataset.low !== undefined && value < +g.dataset.low);
  };
  g._set(min);
}

Array.prototype.forEach.call(document.querySelectorAll('.gauge'), buildGauge);
Array.prototype.forEach.call(document.querySelectorAll('.bar'), buildBar);

// values from Vehicle Spy: only the names that changed are in e.detail
document.addEventListener('vspy', function (e) {
  for (var name in e.detail) {
    var items = document.querySelectorAll('[data-vspy-in="' + name + '"]');
    for (var i = 0; i < items.length; i++)
      if (items[i]._set) items[i]._set(Number(e.detail[name]) || 0);
  }
});

// click the throttle bar: the percentage under the pointer
document.getElementById('throttle-track').addEventListener('click', function (e) {
  var r = e.target.getBoundingClientRect();
  vspy.set('setthrottle', Math.round(clamp((e.clientX - r.left) / r.width, 0, 1) * 100));
});
